struct ppi_if * ppi_create_instance ( struct platform_device * pdev , const struct ppi_info * info ) { struct ppi_if * ppi ; if ( ! info || ! info -> pin_req ) { return in ; } if ( peripheral_request_list ( info -> pin_req , KBUILD_MODNAME ) ) { dev_err ( & pdev -> dev , "request peripheral failed\n" ) ; return NULL ; } ppi = kzalloc ( sizeof ( * ppi ) , GFP_KERNEL ) ; if ( ! ppi ) { peripheral_free_list ( info -> pin_req ) ; dev_err ( & pdev -> dev , "unable to allocate memory for ppi handle\n" ) ; return NULL ; } ppi -> ops = & ppi_ops ; ppi -> info = info ; ppi -> dev = & pdev -> dev ; pr_info ( "ppi probe success\n" ) ; return ppi ; } 